/* Backup copy of the four photos. Normally the site loads images/photo-1..4.jpg.
   If that folder is missing or in the wrong place, this file supplies the same pictures automatically. */
window.PHOTOS = {
  "images/photo-1.jpg": "data:image/jpeg;base64,",
  "images/photo-2.jpg": "data:image/jpeg;base64,",
  "images/photo-3.jpg": "data:image/jpeg;base64,",
  "images/photo-4.jpg": "data:image/jpeg;base64,"
};
function fix(img) {
  if (img.dataset.fallback) return;
  const key = (img.getAttribute("src") || "").split("/").slice(-2).join("/");
  const hit = Object.keys(window.PHOTOS).find(k => k === key || k.split("/").pop() === key.split("/").pop());
  if (hit) { img.dataset.fallback = "1"; img.src = window.PHOTOS[hit]; }
}
document.addEventListener("error", e => { if (e.target.tagName === "IMG") fix(e.target); }, true);
/* safety sweep for any image that failed before this file loaded */
addEventListener("load", () => document.querySelectorAll("img").forEach(i => { if (i.complete && !i.naturalWidth) fix(i); }));
